+    CrossHole {
+        origin: Point3::new(PART_R, 0.0, 0.0),
+        dir: Point3::new(-1.0, 0.0, 0.0),
+        radius: 2.0,
+        entry_d: 0.0,
+        floor_d: -3.0,
+        through: false,
+    }
+}
+
+fn op() -> Operation {
+    Operation {
+        tool: "DR-0400".into(),
+        src: SrcRef::Entity("bar".into()),
+        params: OpParams::Drill {
+            clearance_z: Height::fixed(25.0),
+            retract_z: None,
+            top_z: Height::fixed(20.0),
+            bottom_z: None,
+            cycle: CycleChoice::Auto,
